import{_ as e,o as t,c as a,Q as r}from"./chunks/framework.b67c47e6.js";const n="/assets/designs-bom-page.fbf48690.svg",u=JSON.parse('{"title":"Per-Design BoM","description":"","frontmatter":{},"headers":[],"relativePath":"guide/reports/designs_bom/index.md","filePath":"guide/reports/designs_bom/index.md","lastUpdated":1790354386000}'),s={name:"guide/reports/designs_bom/index.md"},o=r('<h1 id="per-design-bom" tabindex="-1">Per-Design BoM <a class="header-anchor" href="#per-design-bom" aria-label="Permalink to &quot;Per-Design BoM&quot;">​</a></h1><p>The Per-Design Bill of Materials lists the parts per unique design. If multiple assemblies share the same design, the design is listed once, with the number of assemblies next to its name (for example <code>D-11 (x4)</code>).</p><p><img src="'+n+'" alt="A page of a Per-Design BoM"></p><ol><li>The design and how many of the selected assemblies share it.</li><li>One table per branch: timber, plates, and the branches you selected.</li></ol><h2 id="output" tabindex="-1">Output <a class="header-anchor" href="#output" aria-label="Permalink to &quot;Output&quot;">​</a></h2><ul><li><strong>Format:</strong> PDF, or a ZIP with one PDF per phase, batch or panel, depending on the grouping. Designs are deduplicated inside each file.</li><li><strong>Content:</strong> One section per design, starting on a new page: its wood table, its plates table, and a table for each selected branch.</li></ul><h2 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h2><table><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td><strong>Group parts from the report in the same folder</strong></td><td>How the content is split into files: <em>By Phase</em>, <em>By Batch</em> (default), <em>By Panel</em> or <em>By Selected Panels</em> (one single PDF).</td></tr><tr><td><strong>Table style</strong></td><td><em>compact_tables</em> (default) gives one compact table per material type; <em>extended_tables</em> gives the full Wood BoM and Plates BoM tables, with drawings.</td></tr><tr><td><strong>Branches</strong></td><td>The custom branches to add as tables. Branches you do not select are left out.</td></tr><tr><td><strong>Combine</strong></td><td>When the output is a ZIP, also add <em>Combined.pdf</em> with all the PDFs merged.</td></tr><tr><td><strong>Cover Page</strong></td><td>Include a title page with project information. On by default.</td></tr><tr><td><strong>Designs Summary</strong></td><td>Add a summary table of all included designs.</td></tr><tr><td><strong>Show Profile Side Drawings</strong></td><td>Include the wood part drawings (extended tables). On by default.</td></tr><tr><td><strong>Group parts that differ only in length</strong></td><td>On by default. Parts with the same details and a different length share one table and one drawing, with the length shown as LENGTH. See <a href="#parts-that-differ-only-in-length">below</a>.</td></tr><tr><td><strong>Show Plates Drawings</strong></td><td>Include plate drawings (extended tables). On by default.</td></tr><tr><td><strong>Attach to Viewer as DOC</strong></td><td>Link each generated PDF to its assemblies in the Viewer. Only when the output is a ZIP.</td></tr><tr><td><strong>Contact person</strong> / <strong>Delivery address</strong></td><td>Printed on the cover page. Leave empty to use the company&#39;s.</td></tr></tbody></table><h2 id="parts-that-differ-only-in-length" tabindex="-1">Parts that differ only in length <a class="header-anchor" href="#parts-that-differ-only-in-length" aria-label="Permalink to &quot;Parts that differ only in length&quot;">​</a></h2><p>With <strong>Show profile side drawings</strong> on, each wood part with a detail (a drilling, a notch, an angled end cut) gets a table and a drawing of its own. When several parts have exactly the same details and differ only in their length — the studs of a sloped wall, all with the same angled top cut — they now share <strong>one table and one drawing</strong>, with a row per part.</p><ul><li>The drawing shows the length as <strong>LENGTH</strong>, with no number. The real length of each part is in its row.</li><li>The part of the length that changes is drawn short, between two break marks.</li><li>Details before it are measured from the left end, below the drawing. Details after it are measured from the right end, above the drawing, each end with its own 0.</li><li>Only the length may differ: a different width, height, section, material, finish or comment keeps the parts apart. Details must match within 1 mm.</li><li>A part turned end for end or turned over counts as the same part. A mirrored part does not.</li><li>A group has <strong>one</strong> changing length or none. If some parts change before a detail and others after it, they form separate groups.</li></ul><p>Tables go by the part&#39;s <strong>shape</strong>, whichever way round it was modelled, not by its reference. A reference is expected to be one shape, and when it is not, the row says so in red: <em>this reference has more than one shape</em> (its rows are in separate tables) or <em>same shape as another reference</em> (separate rows of one table). In projects created before 26 September 2026, a part modelled turned round still counts as another shape.</p><p>Turn it off with <strong>Group parts that differ only in length</strong> to get one table per part again. The drawing of each part, in the viewer and in logistics, is not affected: it keeps all its numbers.</p><p>With <em>extended_tables</em>, custom branches set as <em>wood alike</em> get the same timber tables as the woods: straight parts in one table, parts with details with their drawing, grouped by length where they can be. With <em>compact_tables</em> they keep their compact table.</p><h2 id="when-to-use" tabindex="-1">When to Use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to Use&quot;">​</a></h2><p>This report type is ideal when you want a complete BoM per design type rather than per physical assembly. Useful for purchasing and material planning where quantities are calculated per design variant.</p>',16),i=[o];function d(l,h,p,g,m,c){return t(),a("div",null,i)}const b=e(s,[["render",d]]);export{u as __pageData,b as default};
